nta.declaration:
// timers_recovery.xml — durable timer / recovery scheduler (INV-T1, T3, T4).
//
// A suspended run carries a deadline D (relative to suspend). A scheduler polls
// every P and, on finding the run due (t >= D), resumes it within a bound B. An
// approval wait times out at Tap but is HELD (not abandoned), so a late decision is
// still delivered (commit 4a8b791). D/P/B/Tap are concrete; the invariants are the
// queries in queries.q. See ../README.md for the tool/verdict table.
//
// LICENSE NOTE: verifyta on this host reports "License does not cover verifier", so
// this timed-automaton model is provided as a REFERENCE only. Because every timing
// constant is an integer, the identical invariants are machine-checked by TLC in the
// discrete-time model ../tla/TimersRecovery.tla, which IS the validated artifact in
// `cargo make fv`. On a host with a verifier-covering UPPAAL license, run:
//   /opt/uppaal/bin/verifyta -q timers_recovery.xml queries.q   (expect: 5x satisfied)
const int D   = 10;   // suspend deadline, relative to suspend
const int P   = 4;    // scheduler poll period
const int B   = 2;    // max latency from a poll deciding to resume, to the resume
const int Tap = 6;    // approval timeout

clock t;    // time since the run suspended
clock pc;   // scheduler poll clock
clock rb;   // scheduler resume-latency clock
clock ta;   // approval clock
clock gc;   // startup clock: offsets the suspend instant from the poll phase

bool suspended = false;   // the run is suspended awaiting its deadline
bool early     = false;   // observer: a resume ever occurred before the deadline

chan resume;
chan decision;

nta.system:
Node1 = Node();
Sched = Scheduler();
Appr  = Approval();
Aver  = Approver();
system Node1, Sched, Appr, Aver;
